--- 数据源来自 excelCfg 配置表；请修改 Excel 后重新执行生成工具。
---@class GeneratedUnitConfig
---@field rawcode string 单位 Rawcode
---@field _parent string|nil 原始单位模板
---@field Name string|nil 单位名称
---@field Ubertip string|nil 单位说明
---@field heroAbilList string|nil 英雄技能 Rawcode 列表
---@field cool1 number|nil 基础攻击间隔（秒）
---@field dmgpt1 number|nil 攻击前摇（秒）；英雄由 unit.xlsx 配置并写入物编
---@field backsw1 number|nil 攻击后摇（秒）；英雄由 unit.xlsx 配置并写入物编
---@field initialAttackSpeedPercent integer|nil 英雄初始总攻速百分比；100%=标准，500%=5 倍；改表后须重新生成地图并重新开局
---@field baseUnitId string|nil PVE 难度变体对应的基础怪物 ID
---@field modeId integer|nil PVE 模式编号：1 普通，2 困难
---@field difficultyLevel integer|nil PVE 难度等级 1–10
---@field tier integer|nil 普通怪与精英的军团阶数（名称后缀“一阶”至“九阶”）
---@field goldRep integer|nil 该物编变体的最终金币奖励
---@field expReward integer|nil 该物编变体的最终经验奖励
---@field poolId string|nil 装备掉落池 ID
---@field dropLevelMin integer|nil 装备最低掉落等级
---@field dropLevelMax integer|nil 装备最高掉落等级
---@field dropChancePercent integer|nil 装备掉落概率；0 表示不掉落
---@field maxDrops integer|nil 最大掉落数
